  { kind: 'signing', label: 'Domain/Message Hash', itemsKey: 'signing', order: 2 },
  { kind: 'override', label: 'State Overrides', itemsKey: 'overrides', order: 3 },
  { kind: 'change', label: 'State Changes', itemsKey: 'changes', order: 4 },
