export const formatBalanceValue = (hex: string): string => {
  try {
    const value = BigInt(hex);
    const wei = value.toString();
    const eth = formatEther(value);
    const normalizedHex = hex.startsWith('0x') ? hex : `0x${hex}`;
    return `${eth} ETH (${wei} wei)\nHex: ${normalizedHex}`;
  } catch {
    return hex;
  }
};

export const formatBalanceDelta = (beforeHex: string, afterHex: string): string => {
  try {
    const before = BigInt(beforeHex);
    const after = BigInt(afterHex);
    const delta = after - before;
    if (delta === BigInt(0)) {
      return '0 ETH (0 wei)';
    }
    const abs = delta >= BigInt(0) ? delta : -delta;
    const sign = delta >= BigInt(0) ? '+' : '-';
    const wei = abs.toString();
    const eth = formatEther(abs);
    return `${sign}${eth} ETH (${sign}${wei} wei)`;
  } catch {
    return `${afterHex} - ${beforeHex}`;
  }
};

export const getFieldDiffs = (expected: string, actual: string): StringDiff[] => {
  if (expected === actual) {
    return [{ type: 'unchanged', value: expected }];
  }

  const diffs: StringDiff[] = [];

  let prefixLength = 0;
  while (
    prefixLength < Math.min(expected.length, actual.length) &&
    expected[prefixLength] === actual[prefixLength]
  ) {
    prefixLength++;
  }

  let suffixLength = 0;
  while (
    suffixLength < Math.min(expected.length - prefixLength, actual.length - prefixLength) &&
    expected[expected.length - 1 - suffixLength] === actual[actual.length - 1 - suffixLength]
  ) {
    suffixLength++;
  }

  if (prefixLength > 0) {
    diffs.push({
      type: 'unchanged',
      value: expected.substring(0, prefixLength),
    });
  }

  const removedPart = expected.substring(prefixLength, expected.length - suffixLength);
  if (removedPart) {
    diffs.push({
      type: 'removed',
      value: removedPart,
    });
  }

  const addedPart = actual.substring(prefixLength, actual.length - suffixLength);
  if (addedPart) {
    diffs.push({
      type: 'added',
      value: addedPart,
    });
  }

  if (suffixLength > 0) {
    diffs.push({
      type: 'unchanged',
      value: expected.substring(expected.length - suffixLength),
    });
  }

  return diffs;
};

const displayDiffs = (expected: string, actual: string, match: boolean) =>
  match ? undefined : getFieldDiffs(expected, actual);

const buildTaskOriginComparisons = (
  validationResult: ValidationData | null
): TaskOriginComparison[] => {
  if (!validationResult?.taskOriginValidation) return [];

  const { enabled, results } = validationResult.taskOriginValidation;

  // If validation is disabled, return a single item representing the disabled state
  if (!enabled) {
    if (validationResult.taskOriginValidation.hidden) return [];
    return [{ results: [], allPassed: true, isDisabled: true }];
  }

  const allPassed = results.every(r => r.success);

  // Return single item containing all results
  return [{ results, allPassed, isDisabled: false }];
};

const buildSigningComparisons = (
  validationResult: ValidationData | null
): SigningDataComparison[] => {
  if (!validationResult) return [];

  const expectedHashes = validationResult.expected.domainAndMessageHashes;
  const actualHashes = validationResult.actual.domainAndMessageHashes;

  if (!expectedHashes || !actualHashes) return [];

  const expectedDataToSign = `0x1901${expectedHashes.domainHash.replace(
    '0x',
    ''
  )}${expectedHashes.messageHash.replace('0x', '')}`;
  const actualDataToSign = `0x1901${actualHashes.domainHash.replace(
    '0x',
    ''
  )}${actualHashes.messageHash.replace('0x', '')}`;

  return [
    {
      contractName: 'EIP-712 Signing Data',
      contractAddress: expectedHashes.address,
      expected: {
        dataToSign: expectedDataToSign,
        address: expectedHashes.address,
        domainHash: expectedHashes.domainHash,
        messageHash: expectedHashes.messageHash,
      },
      actual: {
        dataToSign: actualDataToSign,
        address: actualHashes.address,
        domainHash: actualHashes.domainHash,
        messageHash: actualHashes.messageHash,
      },
    },
  ];
};

const identityKey = (address: string, slot: string): string =>
  `${address.toLowerCase()}:${slot.toLowerCase()}`;

type Pairable<T> = {
  contractName: string;
  contractAddress: string;
  identity: string;
  item: T;
};

const pairByIdentity = <T>(expected: Pairable<T>[], actual: Pairable<T>[]) => {
  const remaining = new Map<string, Pairable<T>[]>();
  for (const entry of actual) {
    const bucket = remaining.get(entry.identity);
    if (bucket) bucket.push(entry);
    else remaining.set(entry.identity, [entry]);
  }

  const rows: Array<{
    contractName: string;
    contractAddress: string;
    expected?: T;
    actual?: T;
  }> = expected.map(entry => {
    const match = remaining.get(entry.identity)?.shift();
    return {
      contractName: entry.contractName,
      contractAddress: entry.contractAddress,
      expected: entry.item,
      actual: match?.item,
    };
  });
  for (const bucket of remaining.values()) {
    for (const entry of bucket) {
      rows.push({
        contractName: entry.contractName,
        contractAddress: entry.contractAddress,
        actual: entry.item,
      });
    }
  }
  return rows;
};

const flattenOverrides = (groups: NonNullable<ValidationData['expected']['stateOverrides']>) =>
  groups.flatMap(group =>
    group.overrides.map(item => ({
      contractName: group.name,
      contractAddress: group.address,
      identity: identityKey(group.address, item.key),
      item,
    }))
  );

const flattenChanges = (groups: NonNullable<ValidationData['expected']['stateChanges']>) =>
  groups.flatMap(group =>
    group.changes.map(item => ({
      contractName: group.name,
      contractAddress: group.address,
      identity: identityKey(group.address, item.key),
      item,
    }))
  );

const buildOverrideComparisons = (
  validationResult: ValidationData | null
): OverrideComparison[] => {
  if (!validationResult) return [];

  return pairByIdentity(
    flattenOverrides(validationResult.expected.stateOverrides ?? []),
    flattenOverrides(validationResult.actual.stateOverrides ?? [])
  );
};

const buildChangeComparisons = (
  validationResult: ValidationData | null
): StateChangeComparison[] => {
  if (!validationResult) return [];

  return pairByIdentity(
    flattenChanges(validationResult.expected.stateChanges ?? []),
    flattenChanges(validationResult.actual.stateChanges ?? [])
  );
};

const buildBalanceComparisons = (
  validationResult: ValidationData | null
): BalanceChangeComparison[] => {
  if (!validationResult) return [];

  const expectedBalances = validationResult.expected.balanceChanges ?? [];
  const actualBalances = validationResult.actual.balanceChanges ?? [];

  return pairByIdentity(
    expectedBalances.map(balance => ({
      contractName: balance.name,
      contractAddress: balance.address,
      identity: identityKey(balance.address, balance.field),
      item: balance,
    })),
    actualBalances.map(balance => ({
      contractName: balance.name,
      contractAddress: balance.address,
      identity: identityKey(balance.address, balance.field),
      item: balance,
    }))
  );
};

export const buildValidationItems = (
  validationResult: ValidationData | null
): ValidationItemsByStep => ({
  taskOrigin: buildTaskOriginComparisons(validationResult),
  signing: buildSigningComparisons(validationResult),
  overrides: buildOverrideComparisons(validationResult),
  changes: buildChangeComparisons(validationResult),
  balance: buildBalanceComparisons(validationResult),
});

export const buildNavList = (items: ValidationItemsByStep): ValidationNavEntry[] => {
  return STEP_DEFINITIONS.flatMap(definition => {
    const stepItems = items[definition.itemsKey];
    return stepItems.map((_, index) => ({ kind: definition.kind, index }));
  });
};

export const getStepCounts = (items: ValidationItemsByStep): StepCounts =>
  STEP_DEFINITIONS.reduce(
    (acc, definition) => {
      acc[definition.itemsKey] = items[definition.itemsKey].length;
      return acc;
    },
    { taskOrigin: 0, signing: 0, overrides: 0, changes: 0, balance: 0 } satisfies StepCounts
  );

const sameHex = (left: string, right: string) => left.toLowerCase() === right.toLowerCase();

const matchesOverride = (comparison: OverrideComparison) =>
  Boolean(
    comparison.expected &&
    comparison.actual &&
    sameHex(comparison.expected.key, comparison.actual.key) &&
    sameHex(comparison.expected.value, comparison.actual.value)
  );

const matchesChange = (comparison: StateChangeComparison) =>
  Boolean(
    comparison.expected &&
    comparison.actual &&
    sameHex(comparison.expected.key, comparison.actual.key) &&
    sameHex(comparison.expected.before, comparison.actual.before) &&
    sameHex(comparison.expected.after, comparison.actual.after)
  );

const matchesBalance = (comparison: BalanceChangeComparison) =>
  Boolean(
    comparison.expected &&
    comparison.actual &&
    comparison.expected.field.toLowerCase() === comparison.actual.field.toLowerCase() &&
    sameHex(comparison.expected.before, comparison.actual.before) &&
    sameHex(comparison.expected.after, comparison.actual.after)
  );

const isUndeclaredOrMismatch = <
  T extends { expected?: { allowDifference?: boolean }; actual?: unknown },
>(
  item: T,
  matches: (item: T) => boolean
): boolean => !item.expected || !item.actual || (!matches(item) && !item.expected.allowDifference);

export const hasBlockingErrors = (items: ValidationItemsByStep): boolean => {
  // Task origin validation failures are blocking (but disabled validation is not a blocking error)
  const taskOriginFailed = items.taskOrigin.some(item => !item.isDisabled && !item.allPassed);
  if (taskOriginFailed) return true;

  const signingMismatch = items.signing.some(
    signing => !signing.actual || signing.expected.dataToSign !== signing.actual.dataToSign
  );
  if (signingMismatch) return true;

  if (items.overrides.some(override => isUndeclaredOrMismatch(override, matchesOverride))) {
    return true;
  }

  if (items.changes.some(change => isUndeclaredOrMismatch(change, matchesChange))) {
    return true;
  }

  return items.balance.some(balance => isUndeclaredOrMismatch(balance, matchesBalance));
};

const defaultContractAddress = (address?: string) =>
  address && address.trim().length > 0 ? address : 'Unknown Address';

const STATUS_ICONS: Record<ValidationMatchStatus['status'], string> = {
  match: 'check',
  mismatch: 'x',
  missing: 'x',
  'expected-difference': 'check',
};

const createMatchStatus = (
  status: ValidationMatchStatus['status'],
  text: string
): ValidationMatchStatus => ({
  status,
  text,
  icon: STATUS_ICONS[status],
});

const assertNever = (value: never): never => {
  throw new Error(`Unhandled entry kind: ${(value as ValidationNavEntry).kind}`);
};

const UNDECLARED_DESCRIPTION: ValidationDescription = {
  variant: 'error',
  icon: 'x',
  title: 'Undeclared Change',
  text: 'The simulation produced this result, but it was not listed in the task config. Signing is blocked until it is declared or removed.',
};

const evaluateUndeclaredEntry = (
  contractName: string,
  contractAddress: string,
  storageKey: string,
  afterValue: string,
  beforeValue?: string
): ValidationEntryEvaluation => ({
  matchStatus: createMatchStatus(
    'mismatch',
    'Unexpected - This result was not declared in the expected config'
  ),
  description: UNDECLARED_DESCRIPTION,
  cards: {
    expected: {
      contractName,
      contractAddress,
      storageKey: NOT_FOUND_TEXT,
      beforeValue: beforeValue === undefined ? undefined : NOT_FOUND_TEXT,
      afterValue: NOT_FOUND_TEXT,
    },
    actual: {
      contractName,
      contractAddress,
      storageKey,
      storageKeyDiffs: getFieldDiffs(NOT_FOUND_TEXT, storageKey),
      beforeValue,
      beforeValueDiffs:
        beforeValue === undefined ? undefined : getFieldDiffs(NOT_FOUND_TEXT, beforeValue),
      afterValue,
      afterValueDiffs: getFieldDiffs(NOT_FOUND_TEXT, afterValue),
      shouldWrap: true,
    },
  },
});

export const evaluateValidationEntry = (
  entry: ValidationNavEntry,
  items: ValidationItemsByStep
): ValidationEntryEvaluation => {
  switch (entry.kind) {
    case 'taskOrigin': {
      const item = items.taskOrigin[entry.index]!;

      const allPassed = item.allPassed;
      const failedCount = item.results.filter(r => !r.success).length;
      const totalCount = item.results.length;

      const matchStatus: ValidationMatchStatus = allPassed
        ? createMatchStatus('match', `All ${totalCount} signature(s) verified`)
        : createMatchStatus('mismatch', `${failedCount} of ${totalCount} signature(s) failed`);

      const descriptionText = allPassed
        ? `This validation verifies that the task bundle has been properly authorized by the required parties (creator and facilitators) before execution. Each signature proves that the designated role has reviewed the task contents.`
        : `Task origin signature verification failed. The task simulation was not run. Please contact developers or facilitators for help before proceeding.`;

      const description: ValidationDescription = {
        variant: allPassed ? 'info' : 'error',
        icon: allPassed ? 'lightbulb' : 'x',
        title: allPassed ? 'Task Authorization' : 'Validation Cannot Proceed',
        text: descriptionText,
      };

      return {
        matchStatus,
        description,
        cards: {
          expected: {
            contractName: 'Task Origin',
            contractAddress: 'Signature Verification',
            storageKey: 'Required Signers',
            afterValue: item.results.map(r => TASK_ORIGIN_ROLE_LABELS[r.role]).join(', '),
          },
          actual: {
            contractName: 'Task Origin',
            contractAddress: 'Verification Results',
            storageKey: 'Status',
            afterValue: allPassed
              ? `All ${totalCount} signatures valid`
              : `${totalCount - failedCount}/${totalCount} valid`,
          },
        },
      };
    }
    case 'signing': {
      const item = items.signing[entry.index]!;
      const expectedData = item.expected.dataToSign;
      const actualData = item.actual?.dataToSign ?? NOT_FOUND_TEXT;
      const match = item.actual ? expectedData === item.actual.dataToSign : false;
      const matchStatus: ValidationMatchStatus = item.actual
        ? match
          ? createMatchStatus('match', 'Match - EIP-712 data matches expected')
          : createMatchStatus('mismatch', 'Mismatch - EIP-712 data does not match expected')
        : createMatchStatus('missing', 'Missing - Not found in actual results');

      const description =
        item.expected.description && item.expected.description.trim().length > 0
          ? ({
              variant: 'info',
              icon: 'lightbulb',
              title: 'What this does',
              text: item.expected.description,
            } satisfies ValidationDescription)
          : undefined;

      return {
        matchStatus,
        description,
        cards: {
          expected: {
            contractName: item.contractName,
            contractAddress: defaultContractAddress(item.contractAddress),
            storageKey: 'EIP-712 Data to Sign',
            afterValue: expectedData,
            shouldWrap: true,
          },
          actual: {
            contractName: item.contractName,
            contractAddress: defaultContractAddress(item.contractAddress),
            storageKey: 'EIP-712 Data to Sign',
            afterValue: actualData,
            afterValueDiffs: getFieldDiffs(expectedData, actualData),
            shouldWrap: true,
          },
        },
      };
    }
    case 'override': {
      const item = items.overrides[entry.index]!;
      if (!item.expected) {
        return evaluateUndeclaredEntry(
          item.contractName,
          defaultContractAddress(item.contractAddress),
          item.actual?.key ?? NOT_FOUND_TEXT,
          item.actual?.value ?? NOT_FOUND_TEXT
        );
      }
      const actualKey = item.actual?.key ?? NOT_FOUND_TEXT;
      const actualValue = item.actual?.value ?? NOT_FOUND_TEXT;
      const match = matchesOverride(item);
      const expectedDifference = item.expected.allowDifference;

      let matchStatus: ValidationMatchStatus;
      if (match) {
        matchStatus = createMatchStatus('match', 'Match - This override is correct');
      } else if (expectedDifference) {
        matchStatus = createMatchStatus(
          'expected-difference',
          'Expected Difference - This mismatch is acceptable and expected'
        );
      } else if (item.actual) {
        matchStatus = createMatchStatus(
          'mismatch',
          'Mismatch - Override values do not match expected'
        );
      } else {
        matchStatus = createMatchStatus('missing', 'Missing - Not found in actual results');
      }

      const description =
        item.expected.description && item.expected.description.trim().length > 0
          ? ({
              variant: expectedDifference ? 'expected-difference' : 'info',
              icon: expectedDifference ? 'check' : 'lightbulb',
              title: expectedDifference ? 'Expected Difference - This is Fine' : 'What this does',
              text: item.expected.description,
            } satisfies ValidationDescription)
          : undefined;

      return {
        matchStatus,
        description,
        cards: {
          expected: {
            contractName: item.contractName,
            contractAddress: defaultContractAddress(item.contractAddress),
            storageKey: item.expected.key,
            afterValue: item.expected.value,
          },
          actual: {
            contractName: item.contractName,
            contractAddress: defaultContractAddress(item.contractAddress),
            storageKey: actualKey,
            storageKeyDiffs: displayDiffs(item.expected.key, actualKey, match),
            afterValue: actualValue,
            afterValueDiffs: displayDiffs(item.expected.value, actualValue, match),
            shouldWrap: !match,
          },
        },
      };
    }
    case 'change': {
      const item = items.changes[entry.index]!;
      if (!item.expected) {
        return evaluateUndeclaredEntry(
          item.contractName,
          defaultContractAddress(item.contractAddress),
          item.actual?.key ?? NOT_FOUND_TEXT,
          item.actual?.after ?? NOT_FOUND_TEXT,
          item.actual?.before ?? NOT_FOUND_TEXT
        );
      }
      const actualKey = item.actual?.key ?? NOT_FOUND_TEXT;
      const actualBefore = item.actual?.before ?? NOT_FOUND_TEXT;
      const actualAfter = item.actual?.after ?? NOT_FOUND_TEXT;
      const match = matchesChange(item);
      const expectedDifference = item.expected.allowDifference;

      let matchStatus: ValidationMatchStatus;
      if (match) {
        matchStatus = createMatchStatus('match', 'Match - This change is correct');
      } else if (expectedDifference) {
        matchStatus = createMatchStatus(
          'expected-difference',
          'Expected Difference - This mismatch is acceptable and expected'
        );
      } else if (item.actual) {
        matchStatus = createMatchStatus(
          'mismatch',
          'Mismatch - Change values do not match expected'
        );
      } else {
        matchStatus = createMatchStatus('missing', 'Missing - Not found in actual results');
      }

      const description =
        item.expected.description && item.expected.description.trim().length > 0
          ? ({
              variant: expectedDifference ? 'expected-difference' : 'info',
              icon: expectedDifference ? 'check' : 'lightbulb',
              title: expectedDifference ? 'Expected Difference - This is Fine' : 'What this does',
              text: item.expected.description,
            } satisfies ValidationDescription)
          : undefined;

      return {
        matchStatus,
        description,
        cards: {
          expected: {
            contractName: item.contractName,
            contractAddress: defaultContractAddress(item.contractAddress),
            storageKey: item.expected.key,
            beforeValue: item.expected.before,
            afterValue: item.expected.after,
          },
          actual: {
            contractName: item.contractName,
            contractAddress: defaultContractAddress(item.contractAddress),
            storageKey: actualKey,
            storageKeyDiffs: displayDiffs(item.expected.key, actualKey, match),
            beforeValue: actualBefore,
            beforeValueDiffs: displayDiffs(item.expected.before, actualBefore, match),
            afterValue: actualAfter,
            afterValueDiffs: displayDiffs(item.expected.after, actualAfter, match),
            shouldWrap: !match,
          },
        },
      };
    }
    case 'balance': {
      const item = items.balance[entry.index]!;
      if (!item.expected) {
        const actualBefore = item.actual ? formatBalanceValue(item.actual.before) : NOT_FOUND_TEXT;
        const actualAfter = item.actual ? formatBalanceValue(item.actual.after) : NOT_FOUND_TEXT;
        return evaluateUndeclaredEntry(
          item.contractName,
          defaultContractAddress(item.contractAddress),
          item.actual?.field ?? NOT_FOUND_TEXT,
          actualAfter,
          actualBefore
        );
      }
      const actualField = item.actual?.field ?? NOT_FOUND_TEXT;
      const match = matchesBalance(item);
      const expectedDifference = item.expected.allowDifference;

      const actualBefore = item.actual ? formatBalanceValue(item.actual.before) : NOT_FOUND_TEXT;
      const actualAfter = item.actual ? formatBalanceValue(item.actual.after) : NOT_FOUND_TEXT;

      let matchStatus: ValidationMatchStatus;
      if (match) {
        matchStatus = createMatchStatus('match', 'Match - Balance change matches expected');
      } else if (expectedDifference) {
        matchStatus = createMatchStatus(
          'expected-difference',
          'Expected Difference - This mismatch is acceptable and expected'
        );
      } else if (item.actual) {
        matchStatus = createMatchStatus(
          'mismatch',
          'Mismatch - Balance change does not match expected'
        );
      } else {
        matchStatus = createMatchStatus('missing', 'Missing - Not found in actual results');
      }

      const expectedBefore = formatBalanceValue(item.expected.before);
      const expectedAfter = formatBalanceValue(item.expected.after);

      const descriptionParts = [
        `Expected delta: ${formatBalanceDelta(item.expected.before, item.expected.after)}`,
        `Actual delta: ${
          item.actual ? formatBalanceDelta(item.actual.before, item.actual.after) : NOT_FOUND_TEXT
        }`,
      ];
      if (item.expected.description) {
        descriptionParts.push(item.expected.description);
      }
      if (item.expected.allowDifference) {
        descriptionParts.push('Differences for this balance change are allowed.');
      }

      const description: ValidationDescription | undefined = descriptionParts.length
        ? {
            variant: expectedDifference ? 'expected-difference' : 'info',
            icon: expectedDifference ? 'check' : 'coins',
            title: expectedDifference
              ? 'Expected Difference - Balance Change OK'
              : 'Balance Change Details',
            text: descriptionParts.join('\n\n'),
          }
        : undefined;

      return {
        matchStatus,
        description,
        cards: {
          expected: {
            contractName: item.contractName,
            contractAddress: defaultContractAddress(item.contractAddress),
            storageKey: item.expected.field,
            beforeValue: expectedBefore,
            afterValue: expectedAfter,
          },
          actual: {
            contractName: item.contractName,
            contractAddress: defaultContractAddress(item.contractAddress),
            storageKey: actualField,
            storageKeyDiffs: displayDiffs(item.expected.field, actualField, match),
            beforeValue: actualBefore,
            beforeValueDiffs: displayDiffs(expectedBefore, actualBefore, match),
            afterValue: actualAfter,
            afterValueDiffs: displayDiffs(expectedAfter, actualAfter, match),
            shouldWrap: !match,
          },
        },
      };
    }
    /* istanbul ignore next */
    default: {
      return assertNever(entry as never);
    }
  }
};

export interface StepInfo {
  currentStep: number;
  currentStepItems: number;
  currentStepIndex: number;
}

export const getStepInfo = (
  entry: ValidationNavEntry | undefined,
  counts: StepCounts
): StepInfo => {
  if (!entry) {
    return {
      currentStep: 0,
      currentStepItems: 0,
      currentStepIndex: 0,
    };
  }

  const definition = STEP_DEFINITION_MAP[entry.kind];
  return {
    currentStep: definition.order,
    currentStepItems: counts[definition.itemsKey],
    currentStepIndex: entry.index + 1,
  };
};

export const getContractNameForEntry = (
  entry: ValidationNavEntry | undefined,
  items: ValidationItemsByStep
): string => {
  if (!entry) return 'Unknown Contract';

  if (entry.kind === 'taskOrigin') {
    return 'Task Origin Signatures';
  }

  const definition = STEP_DEFINITION_MAP[entry.kind];
  const stepItems = items[definition.itemsKey];
  const item = stepItems[entry.index] as { contractName?: string };
  return item?.contractName ?? 'Unknown Contract';
};


